CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.owner_access (email text PRIMARY KEY, CHECK(email=lower(email)));
GRANT ALL ON public.owner_access TO service_role;
ALTER TABLE public.owner_access ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.assign_portfolio_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND (NEW.raw_app_meta_data->'providers') ? 'google' AND EXISTS(SELECT 1 FROM public.owner_access WHERE email=lower(NEW.email)) THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
CREATE TRIGGER portfolio_owner_on_auth AFTER INSERT OR UPDATE OF email_confirmed_at,raw_app_meta_data ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_portfolio_owner();
CREATE TABLE public.projects (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, name text NOT NULL, category text NOT NULL, filter_group text NOT NULL DEFAULT 'Web' CHECK(filter_group IN ('Web','Mobile','Desktop','Design')), description text NOT NULL DEFAULT '', technologies text[] NOT NULL DEFAULT '{}', github_url text NOT NULL DEFAULT '', figma_url text NOT NULL DEFAULT '', live_url text NOT NULL DEFAULT '', image_url text NOT NULL DEFAULT '', image_alt text NOT NULL DEFAULT '', featured boolean NOT NULL DEFAULT false, published boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'In progress', problem text NOT NULL DEFAULT '', solution text NOT NULL DEFAULT '', features text[] NOT NULL DEFAULT '{}', role_text text NOT NULL DEFAULT '', contributions text NOT NULL DEFAULT '', outcomes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.projects TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published projects" ON public.projects FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY "Owner manages projects" ON public.projects FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX projects_published_order ON public.projects(published,sort_order);
CREATE TABLE public.site_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), content jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_settings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_settings TO authenticated; GRANT ALL ON public.site_settings TO service_role;
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public site content" ON public.site_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Owner edits settings" ON public.site_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, group_name text NOT NULL DEFAULT 'Programming', sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.skills TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.skills TO authenticated; GRANT ALL ON public.skills TO service_role;
ALTER TABLE public.skills ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public skills" ON public.skills FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Owner edits skills" ON public.skills FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.media_library (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id text REFERENCES public.projects(id) ON DELETE CASCADE, path text NOT NULL UNIQUE, name text NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL, kind text NOT NULL DEFAULT 'gallery' CHECK(kind IN ('cover','gallery','document','certificate','portrait')), is_public boolean NOT NULL DEFAULT false, caption text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.media_library TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.media_library TO authenticated; GRANT ALL ON public.media_library TO service_role;
ALTER TABLE public.media_library ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public published media" ON public.media_library FOR SELECT TO anon,authenticated USING(is_public AND (project_id IS NULL OR EXISTS(SELECT 1 FROM public.projects WHERE id=project_id AND published)));
CREATE POLICY "Owner manages media" ON public.media_library FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX media_project_idx ON public.media_library(project_id);
CREATE TABLE public.contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, subject text NOT NULL, message text NOT NULL, sender_hash text NOT NULL, is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.contact_messages TO authenticated; GRANT ALL ON public.contact_messages TO service_role;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads inbox" ON public.contact_messages FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX contact_sender_time_idx ON public.contact_messages(sender_hash,created_at);
CREATE TABLE public.activity_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action text NOT NULL, project_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_log TO authenticated; GRANT ALL ON public.activity_log TO service_role;
ALTER TABLE public.activity_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads activity" ON public.activity_log FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.track_project_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN INSERT INTO public.activity_log(action,project_name) VALUES('Deleted',OLD.name); RETURN OLD; END IF; NEW.updated_at=now(); INSERT INTO public.activity_log(action,project_name) VALUES(CASE WHEN TG_OP='INSERT' THEN 'Created' WHEN NEW.published AND NOT OLD.published THEN 'Published' WHEN NOT NEW.published AND OLD.published THEN 'Unpublished' ELSE 'Updated' END,NEW.name); RETURN NEW; END; $$;
CREATE TRIGGER project_activity BEFORE INSERT OR UPDATE OR DELETE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.track_project_change();
CREATE POLICY "Owner uploads media" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='portfolio-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Owner changes media" ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='portfolio-media' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='portfolio-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Owner deletes media" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='portfolio-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Owner reads private files" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='portfolio-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Read explicitly published files" ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='portfolio-media' AND EXISTS(SELECT 1 FROM public.media_library m WHERE m.path=name AND m.is_public AND (m.project_id IS NULL OR EXISTS(SELECT 1 FROM public.projects p WHERE p.id=m.project_id AND p.published))));
CREATE FUNCTION public.reorder_projects(_ids text[]) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.projects p SET sort_order=a.n FROM unnest(_ids) WITH ORDINALITY AS a(id,n) WHERE p.id=a.id; END; $$;
REVOKE ALL ON FUNCTION public.reorder_projects(text[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reorder_projects(text[]) TO authenticated;
CREATE FUNCTION public.accept_contact(_name text,_email text,_subject text,_message text,_sender text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtext(_sender)); IF EXISTS(SELECT 1 FROM public.contact_messages WHERE sender_hash=_sender AND created_at>now()-interval '1 minute') THEN RETURN false; END IF; INSERT INTO public.contact_messages(name,email,subject,message,sender_hash) VALUES(_name,_email,_subject,_message,_sender); RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.accept_contact(text,text,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.accept_contact(text,text,text,text,text) TO service_role;